from pathlib import Path
import json

root = Path(__file__).parent
palette = dict(background='#191A1C',surface='#222326',border='#414246',text='#EFECE5',muted='#B3B0AC',accent='#BDB3E9',cpu='#91B8D5',memory='#C4A6C8',storage='#C7BA95',network='#8CBFBD',ok='#9BC59A',warn='#EBC06A',crit='#ED9185',unavailable='#AAA6A1')
mark = '<path d="M3 15V5H13V9M21 9V19H11V15" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="square" stroke-linejoin="round"/>'
def svg(body, box='0 0 24 24', color='#BDB3E9'):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{box}" color="{color}">{body}</svg>'
(root/'symbol.svg').write_text(svg('<title>Anshin paired open frames</title>'+mark))
(root/'monochrome.svg').write_text(svg('<title>Anshin monochrome symbol</title>'+mark,color='#000000'))
letters = '''<g fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">
<path d="M48 15C48 9 38 9 38 15S48 21 48 15M48 11V20"/>
<path d="M56 20V11M56 15C56 9 66 9 66 15V20"/>
<path d="M83 12C79 8 72 11 74 14C76 17 84 14 83 18C82 22 76 21 73 19"/>
<path d="M91 20V4M91 15C91 9 101 9 101 15V20"/>
<path d="M110 11V20M110 5V5.3"/>
<path d="M119 20V11M119 15C119 9 129 9 129 15V20"/>
</g>'''
word = f'<g transform="translate(1 0)">{mark}</g>{letters}'
(root/'wordmark.svg').write_text(svg('<title>anshin</title>'+word,'0 0 134 26', '#EFECE5'))
icon = f'<rect width="108" height="108" fill="{palette["background"]}"/><g transform="translate(30 30) scale(2)" color="{palette["accent"]}">{mark}</g>'
adaptive = f'''<title>Adaptive icon construction and mask previews</title><defs><clipPath id="round"><circle cx="54" cy="54" r="48"/></clipPath><clipPath id="square"><rect x="6" y="6" width="96" height="96" rx="22"/></clipPath></defs><g>{icon}<circle cx="54" cy="54" r="33" fill="none" stroke="#B3B0AC" stroke-width=".6" stroke-dasharray="2 2"/></g><g transform="translate(118)" clip-path="url(#round)">{icon}</g><g transform="translate(236)" clip-path="url(#square)">{icon}</g><g fill="#B3B0AC" font-family="sans-serif" font-size="9"><text x="8" y="124">108 grid / 66 safe zone</text><text x="148" y="124">Circle mask</text><text x="260" y="124">Rounded mask</text></g>'''
(root/'adaptive-icon.svg').write_text(svg(adaptive,'0 0 344 132'))
concept = {'id':'01-astra','title':'Interval','tagline':'A clear view of your Machines.','summary':'Paired open frames and warm ink surfaces turn a two-Machine Dashboard into a compact, readable register. Muted lilac belongs to navigation and identity; connection state and Verdict each get their own words. Empty space in the mark repeats in honest chart Gaps. The four selectable dark themes keep the same mark, geometry, typography and hierarchy while swapping semantic color tokens. Kanagawa remains the documented default; this exploratory ink palette is an alternative art direction, not a fifth-theme requirement.','personality':['Composed','Observant','Plain-spoken','Exact'],'logoRationale':'Two opposing open frames represent two independent views. Neither encloses the other, matching the direct phone-to-Agent shape. The offset openings leave a recognizable central interval without a heartbeat, shield or implied safety guarantee. The mark uses two continuous paths with a 2.5-unit stroke on a 24-unit grid.','typography':{'ui':'Android system sans / Roboto; system-ui fallback in this board','numbers':'JetBrains Mono with tabular numerals in Compose, per design.md; ui-monospace in this self-contained board','wordmark':'Original vector-drawn lowercase monoline lettering; no font dependency'},'palette':[{'role':k,'hex':v} for k,v in palette.items()],'strengths':['Distinct silhouette in one color','Two Machines fit in a single Dashboard view','Connection state never borrows a reassuring Verdict','Flat rows and restrained color keep values legible'],'tradeoffs':['The abstract mark needs the wordmark during early adoption','The lilac accent will shift under the four documented theme palettes','Dense detail rows need reflow at larger Android font settings','Static HTML cannot validate native interactions or rendering'],'files':{'symbol':'symbol.svg','wordmark':'wordmark.svg','board':'board.html'},'attribution':{'model':'gpt-6-astra','effort':'high'}}
(root/'concept.json').write_text(json.dumps(concept,indent=2)+'\n')

def chart(color='cpu', gap=False):
    paths = ('M0 55L15 52L30 54L45 40L60 44L75 28L90 43L105 40L116 46 M166 48L180 42L195 44L210 31L225 40L240 37L255 65L280 69' if gap else 'M0 55L20 52L40 53L60 48L80 50L100 40L120 47L140 44L160 48L180 40L200 44L220 34L240 39L260 65L280 69')
    empty = '<rect x="125" y="17" width="33" height="63" fill="#191A1C"/><text x="141" y="33" text-anchor="middle" fill="#AAA6A1" font-size="10">Gap</text>' if gap else ''
    return f'<svg viewBox="0 0 280 94" role="img" aria-label="Illustrative CPU percentage over a 30-minute Window'+ (' with a Gap; line segments do not connect across it' if gap else '') +f'"><path d="M0 17H280M0 48H280M0 80H280" stroke="#414246" stroke-width=".6"/>{empty}<path d="{paths}" stroke="{palette[color]}" fill="none" stroke-width="2"/><g fill="#B3B0AC" font-size="9" font-family="monospace"><text x="0" y="11">100%</text><text x="0" y="92">−30 min</text><text x="255" y="92">now</text></g></svg>'

def bar(label, value, width, color):
    return f'<div class="measurement"><span>{label}</span><b>{value}</b><i><em style="width:{width}%;background:var(--{color})"></em></i></div>'
def machine(name, verdict, reason, values):
    return f'''<section class="machine"><div class="row"><h3>{name}</h3><span class="live">● Live</span></div><div class="row sub"><span class="{verdict}">{'△' if verdict=='warn' else '✓'} Verdict · {verdict}</span><span>Pulse · 2 s ago</span></div><div class="meters">{bar('CPU',values[0]+'%',int(values[0]),'cpu')}{bar('Memory',values[1]+'%',int(values[1]),'memory')}{bar('Storage /',values[2]+'%',int(values[2]),'storage')}</div><p class="reason">{reason}</p><div class="row foot"><span>30-minute Window available</span><span class="accent">View Machine →</span></div></section>'''
css = ':root{'+''.join(f'--{k}:{v};' for k,v in palette.items())+'}'
css += '''*{box-sizing:border-box}html,body{margin:0;padding:0;background:transparent}body{color:var(--text);font-family:system-ui,-apple-system,sans-serif;font-size:13px;line-height:1.45}.board{max-width:728px;margin:0 auto;display:grid;gap:14px}.panel{background:var(--background);padding:24px}.identity{display:grid;grid-template-columns:1.2fr 1fr;gap:22px}.wordmark{width:210px;max-width:100%;height:45px;color:var(--text)}h1,h2,h3,p{margin:0}h1{font-weight:500;font-size:26px;letter-spacing:-.7px;margin-top:16px}h2{font-size:18px;font-weight:550;letter-spacing:-.3px}h3{font-size:18px;font-weight:550}.eyebrow{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;color:var(--muted)}.muted,.sub{color:var(--muted)}.intro{margin-top:9px;color:var(--muted);max-width:340px}.marks{display:flex;gap:18px;align-items:center;margin:14px 0}.sample-mark{background:var(--surface);padding:10px;display:flex;align-items:center;gap:12px}.sample-mark svg{width:24px;height:24px}.small{font-size:11px}.adaptive{width:100%;display:block}.palette{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-top:19px}.swatch{height:14px;margin-bottom:5px}.token{font:9px ui-monospace,monospace;white-space:nowrap}.token span{display:block;color:var(--muted);font-size:8px}.screens{display:grid;grid-template-columns:1fr 1fr;gap:14px}.screen-label{font-size:11px;color:var(--muted);margin-bottom:8px;letter-spacing:.6px}.phone{background:var(--background);border:1px solid var(--border);border-radius:20px;overflow:hidden;min-height:800px;display:flex;flex-direction:column}.statusbar{padding:12px 20px 8px;display:flex;justify-content:space-between;font-size:11px}.appbar{padding:8px 18px;min-height:58px;display:flex;align-items:center;gap:12px}.appbar svg{width:119px;height:30px}.icon-button{margin-left:auto;font-size:23px;color:var(--muted);width:40px;height:40px;display:grid;place-items:center}.content{padding:12px 17px 18px;flex:1}.illustrative{font-size:10px;color:var(--muted);border-bottom:1px solid var(--border);padding-bottom:10px;margin-bottom:18px}.summary{border-left:3px solid var(--warn);padding-left:12px;margin:14px 0 20px}.summary h2{font-size:23px;margin:3px 0}.summary p{font-size:12px;color:var(--muted)}.row{display:flex;justify-content:space-between;align-items:center;gap:7px}.live{font-size:11px;color:var(--text)}.warn{color:var(--warn)}.ok{color:var(--ok)}.accent{color:var(--accent)}.machine{border-top:1px solid var(--border);padding:17px 0 14px}.sub{font-size:10px;margin:5px 0 18px}.meters{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.measurement{font-size:10px;color:var(--muted)}b{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-variant-numeric:tabular-nums;font-weight:500}.measurement b{display:block;font-size:22px;color:var(--text);margin-top:2px}.measurement i{display:block;height:3px;background:var(--border);margin-top:9px}.measurement em{display:block;height:3px}.reason{font-size:12px;margin-top:16px}.foot{font-size:9px;color:var(--muted);margin-top:15px;flex-wrap:wrap}.quiet-note{font-size:11px;color:var(--muted);margin-top:18px}.nav{border-top:1px solid var(--border);display:flex;justify-content:space-around;padding:12px 8px;font-size:11px;min-height:57px}.nav span{display:grid;gap:2px;text-align:center}.nav .selected{color:var(--accent)}.gesture{width:88px;height:3px;background:var(--muted);border-radius:3px;margin:8px auto}.detail-heading{margin-bottom:12px}.detail-heading h2{font-size:24px}.verdict{background:var(--surface);border-left:3px solid var(--warn);padding:12px;margin:13px 0 18px}.verdict p{font-size:12px;margin-top:4px}.section{border-top:1px solid var(--border);padding:13px 0}.section h3{font-size:13px}.section .large{font-size:24px;color:var(--cpu)}.chart{margin-top:8px}.chart svg{display:block;width:100%;height:auto}.detail-row{display:flex;justify-content:space-between;gap:10px;font-size:11px;margin:10px 0}.detail-row span{color:var(--muted)}.states{display:grid;grid-template-columns:1fr 1fr;gap:0 24px;margin-top:12px}.state{border-top:1px solid var(--border);padding:13px 0}.state h3{font-size:13px}.state p{font-size:11px;color:var(--muted);margin-top:4px}.state .sample{font:11px ui-monospace,monospace;margin-top:8px;color:var(--unavailable)}.notes{display:grid;grid-template-columns:1fr 1fr;gap:22px}.notes p{color:var(--muted);font-size:11px;margin-top:7px}.notes h3{font-size:13px}@media(max-width:540px){.screens,.identity,.notes{grid-template-columns:1fr}.palette{grid-template-columns:repeat(4,1fr)}.phone{min-height:780px}.panel{padding:20px}.states{gap:0 15px}}'''
colors = ''.join(f'<div class="token"><div class="swatch" style="background:{v}"></div>{k}<span>{v}</span></div>' for k,v in palette.items())
brand = svg(word,'0 0 134 26','#EFECE5')
html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Anshin / Interval design exploration</title><style>{css}</style></head><body><main class="board">
<section class="panel"><div class="identity"><div><div class="wordmark">{brand}</div><h1>A clear view of<br>your Machines.</h1><p class="intro">Interval · warm ink, open frames, quiet lilac. A small register for the two Machines you know.</p></div><div><div class="eyebrow">Original vector identity</div><div class="marks"><div class="sample-mark">{svg(mark)}<span class="small">24 px</span></div><div class="sample-mark" style="color:#EFECE5">{svg(mark,color='#EFECE5')}<span class="small">One color</span></div></div><div class="adaptive">{svg(adaptive,'0 0 344 132')}</div><p class="small muted">Two open frames. A deliberate interval.<br>Foreground stays inside the 66-unit safe circle.</p></div></div><div class="palette">{colors}</div></section>
<div class="screens"><section><div class="screen-label">01 / Dashboard</div><div class="phone"><div class="statusbar"><b>09:41</b><span>▴ ▰</span></div><div class="appbar">{brand}<span class="icon-button" aria-label="Add Machine">+</span></div><div class="content"><div class="illustrative">Illustrative measurements · fictional Machine aliases</div><div class="eyebrow">Your Machines</div><div class="summary"><span class="warn small">△ Worst Verdict · warn</span><h2>Storage needs attention</h2><p>Machine A · both Machines Live</p></div>{machine('Machine A','warn','Reason · Filesystem / is nearly full.',('18','46','92'))}{machine('Machine B','ok','No Reasons from available measurements.',('7','32','61'))}<p class="quiet-note">You read. The Agents measure.<br>Phone traffic stops when you leave the app.</p></div><div class="nav"><span class="selected">▤<br>Machines</span><span>⚙<br>Settings</span></div><div class="gesture"></div></div></section>
<section><div class="screen-label">02 / Machine detail</div><div class="phone"><div class="statusbar"><b>09:41</b><span>▴ ▰</span></div><div class="appbar"><span style="font-size:24px" aria-label="Back">←</span><span>Machine detail</span><span class="icon-button" aria-label="Machine options">⋮</span></div><div class="content"><div class="illustrative">Illustrative measurements · fictional Machine alias</div><div class="row detail-heading"><h2>Machine A</h2><span class="live">● Live</span></div><div class="row small muted"><span>Agent connected</span><span>Pulse · 2 s ago</span></div><div class="verdict"><span class="warn">△ Verdict · warn</span><p>Reason · Filesystem / is nearly full.</p><p><b>92%</b> used · <b>40 GiB</b> available</p></div><div class="section"><div class="row"><h3>CPU</h3><b class="large">18%</b></div><div class="row small muted"><span>30-minute Window</span><span>Total usage</span></div><div class="chart">{chart(gap=True)}</div><div class="detail-row"><span>CPU temperature</span><b>52 °C</b></div></div><div class="section"><div class="row"><h3>Memory</h3><b>46%</b></div><div class="detail-row"><span>Used / total</span><b>7.4 / 16 GiB</b></div><div class="detail-row"><span>Available</span><b>8.6 GiB</b></div></div><div class="section"><div class="row"><h3>Network · summary</h3><span class="small muted">↓ RX / ↑ TX</span></div><div class="detail-row"><b style="color:var(--network)">↓ 240 KiB/s</b><b style="color:var(--network)">↑ 18 KiB/s</b></div></div><div class="section"><div class="detail-row"><span>Battery</span><span>No battery</span></div><div class="detail-row"><span>Disk I/O</span><span>Unavailable</span></div></div><p class="small muted">Gap = no Samples. Lines stop at its edges.<br>Scroll for per-core CPU, filesystems and interfaces.</p></div><div class="gesture"></div></div></section></div>
<section class="panel"><div class="row"><h2>When the view is incomplete</h2><span class="small muted">Illustrative states</span></div><div class="states"><div class="state"><h3>◷ Stale · Machine A</h3><p>Last Pulse 48 s ago. Current Verdict unavailable.</p><div class="sample">Last known CPU · 18% · 48 s ago</div></div><div class="state"><h3>⊘ Unreachable · Machine B</h3><p>Cannot get a Pulse. Last received 6 min ago. Current Verdict unavailable.</p><div class="sample">Retrying automatically while visible</div></div><div class="state"><h3>Unavailable measurement</h3><p>CPU temperature · Unavailable<br>This input is excluded from the Verdict.</p><div class="sample">No value, bar or invented threshold</div></div><div class="state"><h3>Gap in the Window</h3><p>No Samples during this interval. Show empty space at its true duration.</p><div class="sample">Agent restarted? Replace the Window.</div></div><div class="state"><h3>Forbidden</h3><p>The Agent refused this phone. Only the Owner's untagged devices may connect.</p></div><div class="state"><h3>Incompatible</h3><p>This app cannot understand the Agent's Pulse version.</p></div></div></section>
<section class="panel notes"><div><h3>One identity, four dark themes</h3><p>Kanagawa, Tokyo Night, Catppuccin Mocha and Matte Black keep the frames, spacing and type. Theme tokens supply the colors. Kanagawa remains the documented default; ink and lilac is this exploration's proposal.</p></div><div><h3>Native Android, by intent</h3><p>Tap a Machine to inspect it. Back returns to the pair. Flat surfaces, 48 dp targets and scalable type. This HTML is a static design artifact, not a proposed web app or measured product.</p></div></section>
</main></body></html>'''
(root/'board.html').write_text(html)
